<section class="page-head"><div><p class="eyebrow">MAĞAZA ARAMASI</p><h1>“<?= e($searchTerm) ?>” arama sonuçları</h1><p><?= count($searchProducts) ?> ürün bulundu.</p></div></section><form class="search-toolbar" method="get" action="<?= e(url('search')) ?>"><input type="search" name="q" value="<?= e($searchTerm) ?>" minlength="2" maxlength="80" aria-label="Arama kelimesi" required><select name="sort" aria-label="Sıralama"><option value="relevance" <?= $searchSort==='relevance'?'selected':'' ?>>Önerilen</option><option value="newest" <?= $searchSort==='newest'?'selected':'' ?>>En yeni</option><option value="price_asc" <?= $searchSort==='price_asc'?'selected':'' ?>>Fiyat: artan</option><option value="price_desc" <?= $searchSort==='price_desc'?'selected':'' ?>>Fiyat: azalan</option></select><button type="submit">Filtrele</button></form><?php if(mb_strlen($searchTerm,'UTF-8')<2): ?><div class="empty">Arama yapmak için en az 2 karakter girin.</div><?php elseif(!$searchProducts): ?><div class="empty">Aramanızla eşleşen ürün bulunamadı. Farklı bir kelime deneyin.</div><?php else: ?><div class="products"><?php foreach($searchProducts as $p): ?><article class="product"><a class="product-link" href="<?= e(url('product/'.rawurlencode($p['slug']))) ?>"><div class="product-image"><?php if($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span>GAME</span><?php endif; ?></div><small><?= e($p['category_name']??'') ?></small><h3><?= e($p['name']) ?></h3><p><?= e($p['short_description']) ?></p><strong><?= number_format((float)$p['price'],2,',','.') ?> ₺</strong></a></article><?php endforeach; ?></div><?php endif; ?>